@Component
public class LifecycleManagedBean implements InitializingBean, DisposableBean {
    @Autowired
    private Dependency dependency;

    public LifecycleManagedBean() {
        System.out.println("1. Constructor: Bean instantiated");
    }

    @PostConstruct
    public void init() {
        System.out.println("2. @PostConstruct: Dependencies are now ready");
    }

    @Override
    public void afterPropertiesSet() {
        System.out.println("3. InitializingBean: Final setup");
    }

    @PreDestroy
    public void cleanup() {
        System.out.println("4. @PreDestroy: Releasing resources");
    }

    @Override
    public void destroy() {
        System.out.println("5. DisposableBean: Final destruction");
    }
}
